2	import assert from "node:assert/strict";
3	import "../tools/testing/fixtures.mjs";
4	import * as m from "../src/dosing.mjs";
5	
6	test("dosing loads", () => {
7	  assert.ok(Object.keys(m).length > 0);
8	});
9	
10	test("uniqueBedCodes", () => {
11	  assert.deepEqual(m.uniqueBedCodes(['B', 'A', 'B', 'C']), ['B', 'A', 'C']);
12	});
13	
14	test("occupancyFraction", () => {
15	  assert.throws(() => m.occupancyFraction(-5));
16	  assert.throws(() => m.occupancyFraction(101));
17	  assert.equal(m.occupancyFraction(50), 0.5);
18	});
